<?php
session_start();if(!isset($_SESSION["user_id"])){header("Location: login.php");exit;}
require "db.php";require_once "role_helpers.php";require_once "access_helpers.php";require_once "announcement_helpers.php";
$user_id=(int)$_SESSION["user_id"];$st=$conn->prepare("SELECT role,department FROM users WHERE id=? AND active=1");$st->bind_param("i",$user_id);$st->execute();$me=$st->get_result()->fetch_assoc();$st->close();if(!$me){header("Location: login.php");exit;}
$role=$me["role"];$department=$me["department"] ?? "";$module=trim($_GET["module"]??"");$modules=["Project","Task","Event","Team","File","Report","Training","Time Off"];
$r=$conn->query("SELECT a.*,CONCAT(u.first_name,' ',u.last_name) user_name FROM activity_log a INNER JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC,a.id DESC LIMIT 500");$rows=[];
while($r&&$a=$r->fetch_assoc()){if($module!==""&&$a["module"]!==$module)continue;$visible=(int)$a["user_id"]===$user_id;
if(in_array($a["module"],$modules,true)&&$a["record_id"]!==null)$visible=userCanAccessWorkItem($conn,$user_id,$role,$department,$a["module"],(int)$a["record_id"]);
if($role==="Administrator")$visible=true;if($visible){$rows[]=$a;if(count($rows)>=100)break;}}
function e($v){return htmlspecialchars((string)($v??""),ENT_QUOTES,"UTF-8");}
?>
