<main class="main"><div class="header"><div><h1>ACTIVITY</h1><div class="sub">Activity you are permitted to see</div></div></div><div class="content"><form class="card" method="get"><label>Module</label><select name="module"><option value="">All Modules</option><?php foreach($modules as $m):?><option value="<?=e($m)?>" <?=$module===$m?"selected":""?>><?=e($m)?></option><?php endforeach;?></select> <button class="button primary" type="submit">APPLY</button></form><div class="card"><?php if(!$rows):?>No activity available.<?php else:foreach($rows as $a):?><div class="activity-row"><div><div class="activity-user"><?=e($a["user_name"])?></div><div><?=e(date("M j, Y g:i A",strtotime($a["created_at"])))?></div></div><div><div class="activity-meta"><?=e($a["module"])?> · <?=e($a["action_type"])?></div><div><?=e($a["description"])?></div></div><div><?php if(!empty($a["related_url"])):?><a class="button" href="<?=e($a["related_url"])?>">VIEW</a><?php endif;?></div></div><?php endforeach;endif;?></div></div></main></div></body></html>
